# Testo e scaletta visiva del video lungo (un'unica fonte per script.py e scenes.py)
# Caso 030: la Saliera di Benvenuto Cellini (Parigi 1540-1543) rubata al Kunsthistorisches Museum di Vienna (11/5/2003) e ritrovata (21/1/2006)
KHM = "[Kunsthistorisches Museum|Kunst-istòrisces Muséum]"
SC = [
 # 00 INTRO
 (0, "Vienna, maggio 2003. Di notte un uomo sale su un'impalcatura, rompe una finestra di uno dei musei più importanti d'Europa e porta via un capolavoro d'oro del Rinascimento italiano. Valore stimato: circa cinquanta milioni di euro.", [('Vienna', 'mus:0'), ("un'impalcatura", 'mus:1'), ('finestra', 'mus:2'), ('capolavoro', 'sal:0'), ('cinquanta', 'big:≈ 50 mln €|il valore stimato')]),
 (0, "Suona l'allarme. Ma i guardiani pensano a un falso allarme e lo spengono. Il furto si scopre solo la mattina dopo.", [('allarme', 'i:alarm|SUONA L\'ALLARME'), ('guardiani', 'mus:4'), ('mattina', 'sal:1')]),
 (0, "Per quasi tre anni nessuno sa dove sia. Poi una telecamera di un negozio di telefoni cambia tutto. E il ladro si rivela un uomo che nessuno si aspettava: un esperto di sistemi d'allarme.", [('tre', 'i:question|DOV\'È?'), ('telecamera', 'i:cctv|UNA TELECAMERA'), ('esperto', 'i:sensor|UN ESPERTO DI ALLARMI'), ('aspettava', 'stamp:IL LADRO')]),
 (0, "In questo fascicolo vedremo chi era Benvenuto Cellini, come è nata la Saliera, la notte del furto, le richieste di riscatto, la svolta e il processo.", [('In', 'cover'), ('Cellini', 'iii:goldsmith|CELLINI|saliera|LA SALIERA|sms|IL RISCATTO'), ('processo', 't:LA SALIERA DI CELLINI · VIENNA 2003-2006')]),
 # 01 L'EPOCA E IL LUOGO
 (1, "Per capire questo furto bisogna partire da molto lontano: dall'Italia del Cinquecento. È l'epoca del Rinascimento, e Firenze è una delle capitali dell'arte.", [('Per', 'tl:1500|CELLINI NASCE;1540|LA FRANCIA;1543|LA SALIERA;2003|IL FURTO;2006|IL RITROVAMENTO'), ('Cinquecento', 'map:Firenze|20|Firenze,Roma'), ('Firenze', 'h:Firenze,\nil *Rinascimento*')]),
 (1, "In quel mondo gli orafi non sono semplici artigiani. Lavorano l'oro, l'argento, le pietre e gli smalti per papi, principi e re. Molti grandi artisti del tempo hanno cominciato proprio in una bottega d'orafo.", [('orafi', 'i:goldsmith|LA BOTTEGA DELL\'ORAFO'), ('papi', 'iii:crown|PAPI|crown|PRINCIPI|crown|RE'), ('bottega', 'i:workshop|SI COMINCIA DA QUI')]),
 (1, "Prima di tutto, che cos'è una saliera? È il contenitore del sale da tavola. Oggi è un oggetto da pochi euro, ma nelle tavole dei potenti di allora era un pezzo da esibire, al centro del banchetto.", [('saliera', 'h:Che cos\'è\nuna *saliera*?'), ('sale', 'i:salt_pile|IL SALE DA TAVOLA'), ('esibire', 'sal:0')]),
 (1, "Quella di cui parliamo è diversa da tutte le altre. È fatta d'oro, smalto, ebano e avorio, ed è alta circa ventisei centimetri. Oggi la chiamano semplicemente così, con il nome italiano: la Saliera.", [("d'oro", 'iii:gold|ORO|saliera_gold|SMALTO|box_closed|EBANO E AVORIO'), ('ventisei', 'big:≈ 26 cm|di altezza'), ('Saliera', 'sal:0')]),
 (1, f"Ed ecco il luogo dove si svolge il nostro furto, quasi cinque secoli dopo: Vienna, la capitale dell'Austria. Qui c'è il {KHM}, il museo di storia dell'arte, con le grandi collezioni raccolte per secoli dalla famiglia degli Asburgo.", [('luogo', 'map:Vienna|20|Vienna'), ('Kunsthistorisches', 'i:museum|IL MUSEO DI STORIA DELL\'ARTE'), ('Asburgo', 'i:crown|LE COLLEZIONI DEGLI ASBURGO')]),
 (1, "Nel museo ci sono dipinti, sculture e oggetti preziosi e rari, fatti per stupire. E tra i pezzi più famosi, quelli che tutti vengono a vedere, c'è proprio la Saliera.", [('dipinti', 'h:Dipinti, sculture,\n*tesori*'), ('preziosi', 'iii:statue|SCULTURE|gold|ORI|oldbook|RARITÀ'), ('Saliera', 'sal:0')]),
 (1, "Una parola sui soldi. La Saliera non ha un prezzo di mercato: nessuno potrebbe comprarla apertamente. Le fonti, al tempo del furto, la valutano intorno ai cinquanta milioni di euro. Altre, in dollari, parlano di circa sessanta milioni.", [('soldi', 'i:eurobag|UNA STIMA'), ('prezzo', 'stamp:NESSUN PREZZO DI MERCATO'), ('cinquanta', 'big:≈ 50 mln €|stima del valore · 2003-2006'), ('sessanta', 'ii:eurobag|≈ 50 MLN €|eurobag|≈ 60 MLN $')]),
 (1, "Facciamo un conto per capire. Se la Saliera è alta circa ventisei centimetri e vale circa cinquanta milioni, ogni centimetro vale quasi due milioni di euro. Una stima, naturalmente, ma rende l'idea.", [('conto', 'h:Un *conto*'), ('centimetro', 'big:≈ 1,9 mln €|per ogni centimetro · stima'), ('stima', 'stamp:UNA STIMA')]),
 # 02 I PROTAGONISTI
 (2, "Conosciamo i protagonisti, uno per uno. Al centro c'è lei, la Saliera, nata a Parigi tra il 1540 e il 1543.", [('Conosciamo', 'board:0'), ('Saliera', 'sal:0'), ('1540', 'cal:LA SALIERA|1540-1543')]),
 (2, "Poi c'è l'uomo che l'ha creata: Benvenuto Cellini, orafo e scultore fiorentino, nato a Firenze nel 1500. Uno degli artisti più famosi del suo secolo, e anche uno dei più turbolenti.", [('Poi', 'board:1'), ('Cellini', 'card:BENVENUTO CELLINI|orafo e scultore|Firenze · 1500'), ('turbolenti', 'stamp:TURBOLENTO')]),
 (2, "Il terzo è il re che l'ha voluta: Francesco primo, re di Francia, che accoglie alla sua corte artisti venuti dall'Italia, tra cui Cellini.", [('terzo', 'board:2'), ('Francesco', 'i:crown|FRANCESCO I'), ("dall'italia", 'map:Firenze|8|Firenze,Parigi|Firenze>Parigi')]),
 (2, f"Il quarto protagonista è il museo: il {KHM} di Vienna, con il suo direttore di allora, Wilfried [Seipel.|Sàipel.] Nel 2003 l'edificio è in restauro, e sulla facciata c'è un'impalcatura.", [('quarto', 'board:3'), ('museo', 'mus:0'), ('Seipel', 'i:curator|IL DIRETTORE'), ("un'impalcatura", 'i:scaffold|L\'IMPALCATURA')]),
 (2, "Poi ci sono i guardiani del turno di notte: sono tre. Secondo le ricostruzioni hanno un sistema d'allarme collegato con la polizia e telecamere interne.", [('guardiani', 'board:4'), ('tre', 'fig:guard'), ("d'allarme", 'iii:alarm|L\'ALLARME|police|LA POLIZIA|cctv|LE TELECAMERE')]),
 (2, "C'è la compagnia di assicurazioni, l'austriaca [UNIQA,|Unìca,] che ha assicurato l'opera. Sarà lei a ricevere, più avanti, le richieste di riscatto.", [('compagnia', 'board:5'), ('UNIQA', 'i:shield|LA COMPAGNIA ASSICURATRICE'), ('riscatto', 'i:letter|LE RICHIESTE DI RISCATTO')]),
 (2, "Ci sono gli investigatori della polizia di Vienna e dell'ufficio federale di polizia criminale austriaco, che per anni lavoreranno al caso.", [('investigatori', 'board:6'), ('polizia', 'ii:police|POLIZIA DI VIENNA|magnifier|POLIZIA CRIMINALE')]),
 (2, "E poi c'è lui, il ladro. Per quasi tre anni sarà soltanto un punto di domanda. Alla fine avrà un nome: Robert [Mang,|Màng,] cinquant'anni secondo la maggior parte delle fonti, titolare di una ditta di sistemi d'allarme a Vienna.", [('ladro', 'board:7'), ('domanda', 'i:question|PER TRE ANNI: CHI?'), ('Robert', 'card:ROBERT MANG|esperto di sistemi d\'allarme|Vienna · circa 50 anni'), ('ditta', 'i:sensor|SISTEMI D\'ALLARME')]),
 (2, "Riassumiamo. Un capolavoro d'oro, un artista italiano geniale, un re francese, un museo in restauro, tre guardiani, un'assicurazione e un ladro senza volto. Adesso torniamo indietro di cinque secoli, nella bottega di Cellini.", [('Riassumiamo', 'board:7'), ('capolavoro', 'iii:saliera|L\'OPERA|goldsmith|L\'ARTISTA|crown|IL RE'), ('secoli', 'stamp:500 ANNI PRIMA')]),
 # 03 CELLINI E LA NASCITA DELLA SALIERA (la preparazione: come nasce l'oggetto)
 (3, "Benvenuto Cellini nasce a Firenze nel 1500. Le fonti non sono d'accordo sui progetti del padre per lui, ma su una cosa sì: da ragazzo entra a bottega da un orafo fiorentino e impara a lavorare i metalli preziosi.", [('Benvenuto', 'map:Firenze|30|Firenze'), ('1500', 'cal:FIRENZE|1500'), ('orafo', 'i:goldsmith|A BOTTEGA DA UN ORAFO')]),
 (3, "La sua vita è movimentata fin da giovane. Le fonti raccontano più volte guai con la giustizia, processi e fughe da una città all'altra. Non entreremo nei dettagli: qui ci interessa il suo lavoro.", [('movimentata', 'h:Una vita\n*movimentata*'), ('giustizia', 'iii:gavel|PROCESSI|map_icon|FUGHE|scales|ACCUSE'), ('lavoro', 'i:goldsmith|IL LAVORO')]),
 (3, "Si trasferisce a Roma, dove lavora anche per il papa Clemente settimo e per la zecca pontificia: monete, medaglie, gioielli. Nel 1527 è in città durante il drammatico Sacco di Roma.", [('Roma', 'map:Roma|30|Firenze,Roma|Firenze>Roma'), ('papa', 'iii:crown|IL PAPA|gold|MONETE|diamond|GIOIELLI'), ('1527', 'cal:IL SACCO DI ROMA|1527')]),
 (3, "Negli anni successivi, a Roma, viene accusato e chiuso in carcere, e riesce a evadere. Le fonti non concordano sull'anno esatto. Alla fine viene liberato, e secondo Britannica è anche per l'insistenza del cardinale Ippolito d'Este.", [('carcere', 'i:cell|IN CARCERE A ROMA'), ('evadere', 'i:key|EVADE'), ("sull'anno", 'stamp:ANNO NON CONCORDE'), ('Ippolito', 'i:cardinal|IL CARDINALE IPPOLITO D\'ESTE')]),
 (3, "Con il papa successivo, Paolo terzo, le cose cambiano: secondo le fonti lo perdona per una vicenda precedente e gli affida nuovi lavori, tra cui delle monete. Ma la sua vita romana resta agitata.", [('Paolo', 'i:crown|PAOLO III'), ('perdona', 'stamp:PERDONATO'), ('monete', 'i:gold|NUOVE MONETE')]),
 (3, "Ed è proprio per quel cardinale che, secondo le ricostruzioni, Cellini immagina per la prima volta il modello di una saliera straordinaria. Un'idea che però resterà sulla carta fino all'incontro con un re.", [('cardinale', 'i:cardinal|IL PRIMO MODELLO'), ('modello', 'doc:IL PROGETTO|un modello di saliera|per il cardinale|secondo le ricostruzioni'), ('re', 'i:crown|IL RE')]),
 (3, "Nel 1540 Cellini arriva in Francia, alla corte di Francesco primo, che lo accoglie tra i suoi artisti a Fontainebleau e a Parigi.", [('1540', 'cal:IN FRANCIA|1540'), ('Francia', 'map:Parigi|15|Roma,Parigi|Roma>Parigi'), ('Fontainebleau', 'map:Fontainebleau|60|Parigi,Fontainebleau')]),
 (3, "In Francia realizza opere importanti, come il grande rilievo in bronzo della Ninfa di [Fontainebleau,|Fontenblò,] oggi al Louvre. Ma l'opera che lo renderà immortale è un'altra: la saliera per il re.", [('Francia', 'fig:man'), ('Ninfa', 'i:statue|LA NINFA DI FONTAINEBLEAU'), ('saliera', 'sal:0')]),
 (3, "La Saliera nasce tra il 1540 e il 1543. Il tema è il mondo intero, terra e mare. Da una parte siede una figura maschile con il tridente: il dio del mare, Nettuno. Dall'altra una figura femminile: la Terra.", [('1540', 'cal:LA SALIERA|1540-1543'), ('terra', 'h:Terra\ne *mare*'), ('Nettuno', 'i:trident|NETTUNO E IL TRIDENTE'), ('femminile', 'sal:0')]),
 (3, "Secondo le descrizioni dell'opera, accanto a Nettuno c'è una piccola nave, che contiene il sale, che viene dal mare. Accanto alla Terra c'è un tempietto, che contiene il pepe, che viene dalla terra. Ogni dettaglio ha un significato.", [('nave', 'i:ship|LA NAVE · IL SALE'), ('tempietto', 'i:temple|IL TEMPIETTO · IL PEPE'), ('dettaglio', 'stamp:OGNI DETTAGLIO CONTA')]),
 (3, "Sulla base, in ebano, ci sono altre piccole figure: le ore del giorno e i venti. E ci sono i simboli del re di Francia. È un'allegoria del cosmo, da tenere al centro della tavola reale.", [('base', 'sal:0'), ('ore', 'ii:sun|LE ORE DEL GIORNO|wind|I VENTI'), ('simboli', 'i:fleur|I SIMBOLI DEL RE'), ('cosmo', 'h:Il *cosmo*\nsulla tavola')]),
 (3, "Un conto sul tempo: dal 1543, quando la Saliera è finita, al 2003, l'anno del furto, passano quattrocentosessant'anni. Quasi mezzo millennio. E poi una notte di primavera.", [('conto', 'tl:1543|LA SALIERA;1600|;1700|;1800|;1900|;2003|IL FURTO'), ('quattrocentosessant', 'big:460 anni|dalla Saliera al furto')]),
 (3, "Nel 1545 Cellini lascia la Francia e torna a Firenze, dove lavora per il duca Cosimo primo de' Medici. Qui crea un'altra opera celebre: il Perseo in bronzo, svelato nel 1554 sotto la Loggia dei Lanzi.", [('1545', 'map:Firenze|8|Parigi,Firenze|Parigi>Firenze'), ('Cosimo', 'i:crown|COSIMO I DE\' MEDICI'), ('Perseo', 'i:perseus|IL PERSEO'), ('1554', 'cal:IL PERSEO|1554')]),
 (3, "Per Cosimo realizza anche un grande busto in bronzo del duca. E lavora per anni al Perseo, una statua che ancora oggi i turisti fotografano in piazza della Signoria.", [('busto', 'i:statue|IL BUSTO DI COSIMO'), ('Perseo', 'i:perseus|IL PERSEO'), ('turisti', 'crowd')]),
 (3, "Negli ultimi anni scrive. Comincia intorno al 1558 la sua autobiografia, la Vita, che sarà stampata solo nel 1728, e scrive due trattati, sull'oreficeria e sulla scultura. Muore a Firenze nel 1571.", [('scrive', 'i:quill|LA VITA'), ('1558', 'tl:1558|LA VITA;1571|LA MORTE;1728|LA STAMPA'), ('trattati', 'ii:oldbook|L\'OREFICERIA|oldbook|LA SCULTURA'), ('1571', 'cal:FIRENZE|1571')]),
 # 04 IL VIAGGIO DELLA SALIERA E LA NOTTE DEL FURTO
 (4, "E la Saliera? Decenni dopo, un altro re di Francia, Carlo nono, la regala a un arciduca della famiglia d'Asburgo, Ferdinando secondo del Tirolo.", [('Saliera', 'sal:0'), ('Decenni', 'i:fleur|LA CORONA DI FRANCIA'), ('regala', 'flow:CARLO IX>FERDINANDO DEL TIROLO'), ('Tirolo', 'map:Innsbruck|15|Parigi,Innsbruck|Parigi>Innsbruck')]),
 (4, "Ma prima, secondo una ricostruzione, la Saliera corre un rischio enorme: nel 1562 viene quasi fusa, per ricavarne oro. Tenete a mente questa parola, fusa. Tornerà più avanti in questa storia.", [('rischio', 'i:fireplace|QUASI FUSA'), ('1562', 'cal:IL PRIMO RISCHIO|1562'), ('fusa', 'stamp:TENETELO A MENTE')]),
 (4, "Secondo le ricostruzioni, è un ringraziamento: l'arciduca aveva rappresentato il re francese al suo matrimonio con una principessa d'Asburgo. Secondo le stesse ricostruzioni, la Saliera entra nelle collezioni del castello di Ambras, in Tirolo.", [('ringraziamento', 'h:Un *grazie*\nd\'oro'), ('matrimonio', 'i:rings|IL MATRIMONIO'), ('Ambras', 'i:fortress|IL CASTELLO DI AMBRAS')]),
 (4, f"Più tardi, nell'Ottocento, le collezioni si spostano a Vienna, e la Saliera finisce nel {KHM}. Da allora è uno dei pezzi più ammirati della città.", [("nell'ottocento", 'map:Vienna|15|Innsbruck,Vienna|Innsbruck>Vienna'), ('Kunsthistorisches', 'mus:0'), ('ammirati', 'crowd')]),
 (4, "Ed eccoci alla notte del furto. È la notte tra sabato 10 e domenica 11 maggio 2003. Il museo è in restauro e sulla facciata c'è un'impalcatura che arriva fino alle finestre.", [('notte', 'cal:LA NOTTE DEL FURTO|11 MAGGIO 2003'), ('restauro', 'mus:0'), ('finestre', 'i:scaffold|L\'IMPALCATURA')]),
 (4, "Secondo la ricostruzione di un quotidiano austriaco, quella sera il museo ha ospitato un evento notturno, e gli ultimi visitatori sono usciti intorno alle due. Poi il silenzio.", [('quotidiano', 'i:newspaper|SECONDO UNA RICOSTRUZIONE'), ('due', 'clock:2|ESCONO GLI ULTIMI'), ('silenzio', 'i:moon|LA NOTTE')]),
 (4, "Secondo il suo stesso racconto al processo, un uomo passa davanti al museo dopo una serata in discoteca. Ha bevuto. Vede l'impalcatura e decide di salire.", [('racconto', 'stamp:SECONDO IL LADRO'), ("l'impalcatura", 'mus:1')]),
 (4, "Sale piano dopo piano lungo i tubi del cantiere, fino a una finestra. La rompe ed entra nelle sale del museo. Le fonti non concordano su quale piano.", [('Sale', 'i:scaffold_man|SALE SULL\'IMPALCATURA'), ('finestra', 'mus:2'), ('piano', 'stamp:PIANO NON CONCORDE')]),
 (4, "Dentro è buio. L'uomo arriva alla vetrina della Saliera, la rompe e prende l'oggetto. Al processo dirà di aver preso quello che c'era nella vetrina senza sapere quanto valesse.", [('buio', 'i:flashlight|AL BUIO'), ('vetrina', 'i:vitrine|LA VETRINA'), ('rompe', 'mus:3'), ('valesse', 'stamp:SECONDO LUI')]),
 (4, "Alle tre e cinquantacinque, secondo le cronache, scatta l'allarme di un sensore di movimento. In sala sorveglianza i guardiani lo vedono.", [('tre', 'clock:4|3:55 · SCATTA L\'ALLARME'), ('sensore', 'i:sensor|IL SENSORE DI MOVIMENTO'), ('guardiani', 'mus:4')]),
 (4, "Ed ecco l'errore decisivo. I guardiani pensano a un falso allarme, lo confermano e rimettono a posto il sistema. Così l'avviso automatico alla polizia non parte. Nessuno va a controllare la sala.", [("l'errore", 'stamp:L\'ERRORE'), ('falso', 'i:alarm_off|«FALSO ALLARME»'), ('polizia', 'flow:ALLARME>POLIZIA NON AVVISATA'), ('Nessuno', 'mus:4')]),
 (4, "Secondo la stessa ricostruzione, non vengono accese né le luci della sala né le telecamere. Secondo l'agenzia AP, il direttore dirà che il comportamento dei guardiani non si può spiegare.", [('luci', 'ii:bulb|LUCI SPENTE|cctv|TELECAMERE SPENTE'), ('direttore', 'i:curator|«NON SI PUÒ SPIEGARE»')]),
 (4, "Intanto l'uomo esce da dove è entrato: dalla finestra, giù per l'impalcatura, con la Saliera. Quanto tempo resta dentro? Le cronache non danno un numero sicuro.", [('esce', 'mus:1'), ('Saliera', 'sal:0'), ('Quanto', 'i:stopwatch|QUANTO TEMPO?')]),
 (4, "Facciamo il punto per chi ci raggiunge adesso. Notte del giorno 11 maggio 2003. Un uomo sale sull'impalcatura, rompe una finestra e una vetrina, prende la Saliera. L'allarme suona, ma viene considerato falso.", [('punto', 'tl:2:00|ULTIMI VISITATORI;3:55|L\'ALLARME;8:20|LA SCOPERTA'), ("l'allarme", 'i:alarm_off|CONSIDERATO FALSO')]),
 (4, "Se questa storia ti sta piacendo, iscriviti a Fascicolo Italia: ogni giorno un nuovo caso. E adesso, la scoperta.", [('Se', 'subscribe'), ('scoperta', 'sal:1')]),
 # 05 LA SCOPERTA
 (5, "Domenica mattina, verso le otto e venti, qualcuno del personale passa nella sala. La vetrina è rotta e vuota. Le fonti non concordano su chi l'abbia notato per primo: un capo dei sorveglianti o una donna delle pulizie.", [('otto', 'clock:8|8:20 · LA SCOPERTA'), ('vetrina', 'sal:1'), ('fonti', 'ii:guard2|UN SORVEGLIANTE?|woman|UNA ADDETTA ALLE PULIZIE?')]),
 (5, "Solo a quel punto viene chiamata la polizia. Dall'allarme alla scoperta sono passate più di quattro ore. Il ladro ha avuto tutto il tempo per sparire.", [('polizia', 'i:policecar|ARRIVA LA POLIZIA'), ('quattro', 'big:> 4 ore|dall\'allarme alla scoperta'), ('sparire', 'stamp:SPARITO')]),
 (5, "La notizia fa il giro del mondo. Il pezzo più famoso del museo, un capolavoro del Rinascimento, è stato rubato salendo su un'impalcatura, mentre i guardiani spegnevano l'allarme.", [('notizia', 'i:newspaper|LA NOTIZIA FA IL GIRO DEL MONDO'), ("un'impalcatura", 'mus:2'), ('guardiani', 'i:alarm_off|L\'ALLARME SPENTO')]),
 (5, "I tre guardiani vengono sospesi in attesa delle indagini. Il direttore [Seipel|Sàipel] offre le dimissioni, ma la ministra della cultura, Elisabeth [Gehrer,|Ghèrer,] le respinge e indica la responsabilità nei sorveglianti.", [('sospesi', 'stamp:SOSPESI'), ('dimissioni', 'i:letter|LE DIMISSIONI'), ('respinge', 'stamp:RESPINTE'), ('responsabilità', 'mus:4')]),
 (5, "Pochi giorni dopo, secondo un quotidiano austriaco, il direttore parla del furto come di un attacco al patrimonio culturale del mondo intero. Non è solo una perdita per Vienna.", [('direttore', 'i:curator|IL DIRETTORE'), ('patrimonio', 'h:Un attacco al\n*patrimonio* del mondo'), ('Vienna', 'map:Vienna|8|Vienna,Parigi,Firenze')]),
 (5, "Secondo un quotidiano austriaco, il museo viene criticato per le misure di sicurezza e per l'impalcatura lasciata senza protezioni. E secondo l'agenzia AP, nel mese precedente c'erano stati altri falsi allarmi.", [('criticato', 'i:megaphone|LE CRITICHE'), ("l'impalcatura", 'i:scaffold|SENZA PROTEZIONI'), ('falsi', 'stamp:ALTRI FALSI ALLARMI')]),
 (5, "Viene offerta una ricompensa a chi aiuterà a ritrovare l'opera. Le cifre cambiano da fonte a fonte e nel tempo, da settantamila euro a più di ottantamila dollari.", [('ricompensa', 'i:eurobag|UNA RICOMPENSA'), ('cifre', 'ii:eurobag|70.000 €?|eurobag|> 80.000 $?'), ('fonte', 'stamp:CIFRE NON CONCORDI')]),
 (5, "E arriva la domanda che tutti si fanno: chi può rubare un oggetto così famoso? Non si può vendere: ogni collezionista, ogni antiquario, ogni casa d'aste del mondo lo riconoscerebbe.", [('domanda', 'i:question|CHI?'), ('vendere', 'stamp:IMPOSSIBILE DA VENDERE'), ('collezionista', 'iii:magnifier|COLLEZIONISTI|shop|ANTIQUARI|gavel|CASE D\'ASTE')]),
 (5, "Le ipotesi sono tante: un ladro su commissione per un collezionista segreto, una banda internazionale, qualcuno che vuole un riscatto. Oppure un oro da fondere. È questa la paura più grande.", [('ipotesi', 'h:Le *ipotesi*'), ('commissione', 'iii:villa|UN COLLEZIONISTA?|map_icon|UNA BANDA?|letter|UN RISCATTO?'), ('fondere', 'i:fireplace|FONDERLA?'), ('paura', 'stamp:LA PAURA')]),
 # 06 L'INDAGINE
 (6, "Comincia un'indagine lunga e difficile. All'inizio gli investigatori hanno poco in mano: un'impalcatura, una finestra rotta e una vetrina vuota.", [("un'indagine", 'i:magnifier|L\'INDAGINE'), ('poco', 'iii:scaffold|L\'IMPALCATURA|window|LA FINESTRA|vitrine_broken|LA VETRINA'), ('vuota', 'sal:1')]),
 (6, "Una pista viene esaminata: che qualcuno dall'interno del museo abbia aiutato il ladro. Secondo un quotidiano austriaco, la polizia dirà di averla verificata senza alcun risultato.", [('pista', 'i:museum|UN AIUTO DALL\'INTERNO?'), ('risultato', 'stamp:NESSUN RISULTATO')]),
 (6, "Arrivano anche false piste. Secondo lo stesso quotidiano, pochi giorni dopo il furto spunta su un sito americano l'offerta di un servizio da sale e pepe: è uno scherzo. A luglio si tenta perfino un riacquisto con un annuncio su un quotidiano internazionale.", [('false', 'stamp:FALSE PISTE'), ('sito', 'i:tvcam|UN SITO AMERICANO'), ('scherzo', 'i:question|UNO SCHERZO'), ('annuncio', 'i:newspaper|UN ANNUNCIO')]),
 (6, "Passano le settimane, poi i mesi. Nel 2003 alla compagnia di assicurazioni arriva una lettera con una richiesta di riscatto e, insieme, frammenti che il mittente dice di aver staccato dalla Saliera.", [('settimane', 'cal:IL CASO SI FERMA|2003'), ('lettera', 'doc:LETTERA ANONIMA|alla compagnia assicuratrice|richiesta di riscatto|con frammenti'), ('frammenti', 'i:shards|FRAMMENTI?')]),
 (6, "Le cifre di quella prima richiesta non coincidono: secondo un quotidiano austriaco cinque milioni di euro, secondo un'agenzia americana sei milioni di dollari. Anche l'autenticità dei frammenti viene discussa.", [('cifre', 'ii:eurobag|5 MLN €?|eurobag|6 MLN $?'), ("l'autenticità", 'stamp:AUTENTICI?')]),
 (6, "Secondo lo stesso quotidiano, seguono annunci in codice sui giornali e perfino una pagina internet, per tenere aperto il contatto. Ma per molto tempo non arriva nessuna risposta.", [('annunci', 'i:newspaper|ANNUNCI IN CODICE'), ('risposta', 'i:hourglass|NESSUNA RISPOSTA')]),
 (6, "Nel maggio 2004, a un anno dal furto, un'agenzia americana scrive che non c'è ancora nessuna traccia. La Saliera potrebbe essere ovunque: in una cassaforte all'estero, in una cantina, o già fusa.", [('2004', 'cal:UN ANNO DOPO|MAGGIO 2004'), ('traccia', 'stamp:NESSUNA TRACCIA'), ('ovunque', 'iii:safe|IN UNA CASSAFORTE?|house|IN UNA CANTINA?|fireplace|FUSA?')]),
 (6, "Sempre nel maggio 2004, secondo un quotidiano austriaco, un impostore si presenta come intermediario e porta il direttore del museo fino in Italia. L'uomo viene arrestato. Con la Saliera non aveva niente a che fare.", [('impostore', 'i:question|UN FALSO INTERMEDIARIO'), ('Italia', 'map:Roma|8|Vienna,Roma|Vienna>Roma'), ('arrestato', 'stamp:ARRESTATO'), ('niente', 'stamp:NON C\'ENTRA')]),
 (6, "Un riepilogo per chi entra adesso. Maggio 2003: la Saliera viene rubata salendo su un'impalcatura, mentre l'allarme viene spento come falso. Un anno dopo, nessuna traccia. E sulle richieste di riscatto, solo dubbi.", [('riepilogo', 'tl:MAG 2003|IL FURTO;2003|LA PRIMA LETTERA;MAG 2004|NESSUNA TRACCIA'), ('dubbi', 'i:question|SOLO DUBBI')]),
 (6, "Nel 2005 il ricattatore si fa di nuovo vivo, con la compagnia di assicurazioni [UNIQA.|Unìca.] Questa volta la richiesta è chiara: dieci milioni di euro.", [('2005', 'cal:IL RICATTO|2005'), ('UNIQA', 'i:shield|LA COMPAGNIA ASSICURATRICE'), ('dieci', 'big:10 mln €|la richiesta di riscatto')]),
 (6, "E c'è una minaccia. Se i soldi non arrivano, la Saliera verrà fusa. Un capolavoro di quasi cinque secoli trasformato in un pezzo d'oro qualsiasi.", [('minaccia', 'stamp:LA MINACCIA'), ('fusa', 'i:fireplace|«LA FONDO»'), ('qualsiasi', 'ii:saliera|IL CAPOLAVORO|gold|SOLO ORO')]),
 (6, "Facciamo un conto. Dieci milioni sono un quinto del valore stimato, cinquanta milioni. Per il ricattatore, una cifra enorme. Per il patrimonio dell'Austria, una perdita molto più grande se l'opera venisse distrutta.", [('conto', 'h:Un *conto*'), ('quinto', 'big:1/5|il riscatto rispetto al valore stimato'), ('perdita', 'stamp:INSOSTITUIBILE')]),
 (6, "Per dimostrare di avere davvero la Saliera, nell'ottobre del 2005 il ricattatore fa arrivare agli investigatori un pezzo staccabile dell'opera: il tridente di Nettuno.", [('dimostrare', 'h:Una *prova*'), ("nell'ottobre", 'cal:LA PROVA|OTTOBRE 2005'), ('tridente', 'i:trident|IL TRIDENTE DI NETTUNO')]),
 (6, "È la prova che l'opera esiste ancora, e che non è stata fusa. Ma la polizia tiene la notizia segreta, e la renderà pubblica solo mesi dopo, a gennaio del 2006.", [('prova', 'i:trident|ESISTE ANCORA'), ('segreta', 'i:lock|TENUTA SEGRETA'), ('gennaio', 'cal:RESA PUBBLICA|GENNAIO 2006')]),
 (6, "Intanto c'è anche una partita tra lo Stato e l'assicurazione su chi debba ricevere un eventuale indennizzo. Secondo un quotidiano austriaco, a dicembre 2005 la ministra della cultura dice che l'assicurazione non ha ancora pagato.", [('partita', 'ii:museum|LO STATO|shield|L\'ASSICURAZIONE'), ('dicembre', 'cal:NON ANCORA PAGATO|DICEMBRE 2005')]),
 (6, "Il 7 novembre 2005 comincia la consegna del riscatto. Il ricattatore guida l'incaricato che porta i soldi per tutta Vienna, con messaggi sul telefono e bigliettini lasciati in vari punti della città.", [('7', 'cal:LA CONSEGNA|7 NOVEMBRE 2005'), ('Vienna', 'map:Vienna|160|Vienna'), ('telefono', 'ii:sms|MESSAGGI SUL TELEFONO|letter|BIGLIETTINI')]),
 (6, "È una specie di caccia al tesoro, che va avanti per tutto il giorno. Secondo l'ufficio di polizia criminale, a seguire tutto c'è una squadra speciale di pedinamento, insieme ad altri reparti.", [('caccia', 'h:Una *caccia*\nal tesoro'), ('squadra', 'iii:binoculars|PEDINAMENTO|policecar|LE AUTO|police|GLI AGENTI')]),
 (6, "Ma la consegna non avviene mai. In serata il contatto si interrompe: il ricattatore sparisce di nuovo. Nessun soldo passa di mano, e la Saliera resta nascosta.", [('consegna', 'stamp:NESSUNA CONSEGNA'), ('serata', 'i:moon|IL CONTATTO SI INTERROMPE'), ('nascosta', 'i:question|ANCORA NASCOSTA')]),
 (6, "E secondo la rivista del ministero dell'Interno austriaco, dagli interrogatori successivi emergerà un dettaglio: il ricattatore non si era accorto di nessun pedinamento.", [('rivista', 'i:oldbook|LA RIVISTA DEL MINISTERO'), ('pedinamento', 'i:binoculars|NESSUNO SE NE ACCORGE')]),
 (6, "Le fonti non concordano su quanti siano stati i tentativi di riscatto: un grande quotidiano americano ne conta due, altre ricostruzioni parlano soprattutto di quella giornata di novembre.", [('fonti', 'ii:sms|UN TENTATIVO?|sms|DUE TENTATIVI?'), ('novembre', 'stamp:FONTI NON CONCORDI')]),
 # 07 LA SVOLTA
 (7, "Eppure quella giornata lascia una traccia. Il ricattatore ha usato un telefono cellulare per mandare i messaggi. E quel telefono, da qualche parte, è stato comprato.", [('traccia', 'h:Una *traccia*'), ('telefono', 'i:sms|IL TELEFONO DEL RICATTO'), ('comprato', 'stamp:DOVE È STATO COMPRATO?')]),
 (7, "Gli investigatori risalgono al negozio dove è stato comprato: un negozio di telefoni a Vienna. E nel negozio c'è una telecamera di sorveglianza. Ha ripreso l'uomo mentre lo comprava.", [('negozio', 'i:shop|IL NEGOZIO DI TELEFONI'), ('telecamera', 'i:cctv|LA TELECAMERA DEL NEGOZIO'), ('comprava', 'i:nophoto|UN VOLTO')]),
 (7, "Venerdì 20 gennaio 2006 la polizia fa una mossa decisiva. Annuncia di avere il tridente, e pubblica le immagini dell'uomo ripreso dalla telecamera, chiedendo a chiunque lo riconosca di farsi avanti.", [('20', 'cal:LA SVOLTA|20 GENNAIO 2006'), ('tridente', 'i:trident|«ABBIAMO IL TRIDENTE»'), ('immagini', 'i:tvcam|LE IMMAGINI IN TV E SUI GIORNALI'), ('riconosca', 'stamp:LO RICONOSCETE?')]),
 (7, "Le immagini finiscono in televisione e sui giornali. Secondo le ricostruzioni, alcuni conoscenti lo riconoscono. E l'uomo, vista la sua faccia ovunque, si presenta alla polizia.", [('televisione', 'i:newspaper|LA FOTO OVUNQUE'), ('conoscenti', 'iii:woman|«È LUI!»|man|«È LUI!»|woman2|«È LUI!»'), ('presenta', 'i:police|SI PRESENTA ALLA POLIZIA')]),
 (7, "Le fonti non concordano sul giorno esatto: per alcune si consegna il venerdì stesso, per altre il giorno dopo. Il suo nome è Robert [Mang.|Màng.] E la sua professione lascia tutti di stucco.", [('giorno', 'ii:calendar_x|20 GENNAIO?|calendar_x|21 GENNAIO?'), ('Robert', 'card:ROBERT MANG|si presenta alla polizia|gennaio 2006'), ('professione', 'stamp:LA SORPRESA')]),
 (7, "È un esperto di sistemi d'allarme, titolare di una sua ditta a Vienna. Secondo la polizia, un imprenditore senza problemi economici e senza precedenti penali.", [('esperto', 'i:sensor|ESPERTO DI ALLARMI'), ('titolare', 'i:shop|UNA SUA DITTA'), ('precedenti', 'ii:eurobag|NESSUN PROBLEMA DI SOLDI|shield_ok|NESSUN PRECEDENTE')]),
 (7, "Il paradosso è perfetto: l'uomo che di mestiere protegge case e negozi dai ladri è entrato in uno dei musei più famosi d'Europa e ne è uscito con il suo pezzo più prezioso.", [('paradosso', 'h:Il *paradosso*'), ('protegge', 'ii:sensor|DI GIORNO: PROTEGGE|scaffold_man|DI NOTTE: ENTRA'), ('prezioso', 'sal:0')]),
 (7, "Interrogato dagli investigatori, confessa. E accetta di portare gli investigatori dove ha nascosto la Saliera.", [('Interrogato', 'clock:10|L\'INTERROGATORIO'), ('confessa', 'i:signature|CONFESSA'), ('nascosto', 'i:question|DOVE?')]),
 (7, "Il viaggio porta fuori Vienna, nella zona di [Zwettl,|Zvètl,] circa novanta chilometri dalla capitale. Una zona di campagna e di boschi.", [('viaggio', 'map:Zwettl|60|Vienna,Zwettl|Vienna>Zwettl'), ('novanta', 'big:≈ 90 km|da Vienna'), ('boschi', 'i:forest_box|I BOSCHI')]),
 (7, "Lì, in un bosco, sotto terra, c'è una cassa sepolta. Le fonti non concordano sul materiale: per alcune è di legno, per altre di piombo. Dentro c'è la Saliera.", [('bosco', 'sal:2'), ('cassa', 'ii:box_closed|DI LEGNO?|box_closed|DI PIOMBO?'), ('Saliera', 'i:box_open|LA SALIERA')]),
 (7, "È sabato 21 gennaio 2006. La cassa viene aperta e gli esperti verificano che l'opera è autentica. Dopo quasi tre anni, la Saliera è stata ritrovata.", [('21', 'cal:IL RITROVAMENTO|21 GENNAIO 2006'), ('autentica', 'stamp:AUTENTICA'), ('ritrovata', 'sal:3')]),
 (7, "Un conto sul tempo: dal giorno 11 maggio 2003 al 21 gennaio 2006 passano novecentottantasei giorni. Quasi mille giorni lontano dal museo.", [('conto', 'tl:11 MAG 2003|IL FURTO;20 GEN 2006|LE FOTO;21 GEN 2006|IL BOSCO'), ('novecentottantasei', 'big:986 giorni|lontano dal museo')]),
 (7, "Il giorno dopo, 22 gennaio, la ministra dell'Interno, [Liese|Lìse] [Prokop,|Pròkop,] restituisce la Saliera alla ministra della cultura e al museo, in una consegna simbolica.", [('22', 'cal:LA RESTITUZIONE|22 GENNAIO 2006'), ('restituisce', 'flow:POLIZIA>MUSEO'), ('simbolica', 'i:museum|DI NUOVO AL MUSEO')]),
 (7, "E dal 31 gennaio 2006 il pubblico può tornare a vederla nel museo. Il pubblico torna davanti alla vetrina.", [('31', 'cal:DI NUOVO IN MOSTRA|31 GENNAIO 2006'), ('pubblico', 'sal:3'), ('torna', 'crowd')]),
 # 08 IL PROCESSO
 (8, "Resta il processo. Robert [Mang|Màng] è accusato di furto aggravato e di tentata estorsione, cioè del ricatto all'assicurazione.", [('processo', 'court:IL TRIBUNALE DI VIENNA'), ('accusato', 'ii:scaffold_man|FURTO AGGRAVATO|letter|TENTATA ESTORSIONE')]),
 (8, "In aula racconta la sua versione. Non aveva un piano: quella notte era ubriaco, tornava da una discoteca, ha visto l'impalcatura e ha deciso di salire. Secondo lui, voleva solo dimostrare di poter entrare.", [('aula', 'i:court|LA SUA VERSIONE'), ('ubriaco', 'stamp:«ERO UBRIACO»'), ("l'impalcatura", 'mus:1'), ('dimostrare', 'h:Voleva *dimostrare*\ndi poter entrare')]),
 (8, "Dice anche di non aver avuto bisogno di soldi. Secondo il suo racconto, l'idea del ricatto gli è venuta più tardi, leggendo quanto i giornali parlavano del furto.", [('soldi', 'i:eurobag|«NON MI SERVIVANO SOLDI»'), ('ricatto', 'i:letter|L\'IDEA DEL RICATTO'), ('giornali', 'i:newspaper|«DAI GIORNALI»')]),
 (8, "Settembre 2006: il tribunale di Vienna lo condanna a quattro anni di carcere per furto aggravato. Per l'estorsione, invece, in quel primo processo non viene condannato.", [('Settembre', 'cal:PRIMA SENTENZA|SETTEMBRE 2006'), ('quattro', 'big:4 anni|furto aggravato · primo processo'), ("l'estorsione", 'stamp:NON CONDANNATO PER IL RICATTO')]),
 (8, "Ma la sentenza viene impugnata. All'inizio del 2007 la Corte suprema austriaca la annulla. Secondo il quotidiano Der Standard, per un errore di diritto: la minaccia di fondere la Saliera andava giudicata come tentata estorsione aggravata. Il processo va rifatto.", [('impugnata', 'i:gavel|IL RICORSO'), ('Corte', 'court:LA CORTE SUPREMA'), ('annulla', 'stamp:ANNULLATA'), ('rifatto', 'i:hourglass|DA RIFARE')]),
 (8, "26 giugno 2007, nuovo processo a Vienna. Questa volta la condanna è a cinque anni, per furto aggravato e tentata estorsione aggravata.", [('26', 'cal:SECONDA SENTENZA|26 GIUGNO 2007'), ('cinque', 'big:5 anni|furto e tentata estorsione aggravata')]),
 (8, "Tra le attenuanti, secondo le cronache del processo, la sua fedina penale pulita, la confessione e la disponibilità a risarcire i danni.", [('attenuanti', 'h:Le *attenuanti*'), ('fedina', 'iii:shield_ok|NESSUN PRECEDENTE|signature|LA CONFESSIONE|eurobag|IL RISARCIMENTO')]),
 (8, "Nell'agosto del 2008 il tribunale competente gli concede la liberazione condizionale anticipata. Esce a fine ottobre. Le fonti non concordano sul conto esatto: ha passato in carcere circa due anni e sette mesi, o due anni e nove mesi.", [('2008', 'cal:LIBERO|2008'), ('condizionale', 'stamp:LIBERAZIONE ANTICIPATA'), ('nove', 'ii:hourglass|2 ANNI E 7 MESI?|hourglass|2 ANNI E 9 MESI?')]),
 (8, "Un ultimo conto: condannato a cinque anni, ne sconta meno di tre. E da allora, secondo le cronache austriache, evita la pubblicità e non parla con i giornalisti.", [('conto', 'big:5 anni · < 3|condanna · anni scontati'), ('pubblicità', 'i:microphone|NESSUNA INTERVISTA')]),
 # 09 COSA È SUCCESSO DOPO
 (9, "E la Saliera? Quando la cassa viene aperta, l'opera è quasi intatta. Ma non del tutto. Ha piccoli graffi sull'oro e alcuni danni allo smalto.", [('Saliera', 'sal:3'), ('intatta', 'stamp:QUASI INTATTA'), ('graffi', 'ii:saliera_gold|GRAFFI SULL\'ORO|magnifier|DANNI ALLO SMALTO')]),
 (9, "Secondo le ricostruzioni, i graffi sono dovuti ai vetri della vetrina rotta e alla conservazione sbagliata durante i mesi in cui è rimasta nascosta. Serve un restauro.", [('vetri', 'i:vitrine_broken|I VETRI ROTTI'), ('conservazione', 'i:forest_box|LA CASSA SEPOLTA'), ('restauro', 'i:magnifier|IL RESTAURO')]),
 (9, "Le cronache del processo del 2007 dicono che il restauro, a quella data, non era ancora finito. Lavorare su un oggetto così delicato richiede tempo.", [('restauro', 'i:goldsmith|IL RESTAURO'), ('finito', 'stamp:NON ANCORA FINITO'), ('tempo', 'i:hourglass|TEMPO')]),
 (9, "Intanto il museo lavora alla sua camera delle meraviglie, la sezione degli oggetti preziosi, che riaprirà dopo una lunga ristrutturazione.", [('lavora', 'mus:0'), ('meraviglie', 'h:La camera\ndelle *meraviglie*'), ('ristrutturazione', 'i:scaffold|LA RISTRUTTURAZIONE')]),
 (9, f"Nel 2013, a partire dal primo marzo, la Saliera torna esposta in modo permanente nella camera delle meraviglie riaperta del {KHM}. Oggi è di nuovo al suo posto, al centro dell'attenzione.", [('2013', 'cal:DI NUOVO AL SUO POSTO|MARZO 2013'), ('permanente', 'sal:3'), ("dell'attenzione", 'crowd')]),
 (9, "Dopo il furto, al ministero si tiene un vertice sulla sicurezza dei musei. Secondo un quotidiano austriaco, la conclusione è che le misure tecniche sono in gran parte sufficienti, ma che va curato il fattore umano.", [('vertice', 'i:meeting|IL VERTICE SULLA SICUREZZA'), ('tecniche', 'ii:sensor|LA TECNICA: OK|guard2|LE PERSONE: DA MIGLIORARE'), ('umano', 'h:Il fattore\n*umano*')]),
 (9, "Ed è questa la lezione più amara: l'allarme aveva funzionato. Il sensore aveva visto il ladro. Ma le persone che dovevano reagire non l'hanno fatto.", [("l'allarme", 'i:alarm|L\'ALLARME HA FUNZIONATO'), ('sensore', 'i:sensor|IL SENSORE LO HA VISTO'), ('persone', 'mus:4')]),
 (9, "C'è anche la questione dei soldi. Secondo le cronache del processo, il ladro versa un risarcimento al museo e all'assicurazione per coprire le spese, e il suo avvocato dichiara il danno completamente risarcito.", [('soldi', 'i:eurobag|I SOLDI'), ('risarcimento', 'ii:museum|AL MUSEO|shield|ALL\'ASSICURAZIONE'), ('avvocato', 'stamp:DANNO RISARCITO')]),
 (9, "Riepilogo per chi entra adesso. Maggio 2003: il furto. Ottobre 2005: il tridente. Novembre 2005: la caccia al tesoro fallita. Gennaio 2006: le immagini, la confessione, il bosco. 2007: la condanna a cinque anni. 2013: la Saliera di nuovo in mostra per sempre.", [('Riepilogo', 'tl:2003|FURTO;2005|RICATTO;2006|BOSCO;2007|5 ANNI;2013|IN MOSTRA'), ('2013', 'sal:3')]),
 # 10 LE DOMANDE APERTE
 (10, "Come in ogni caso, restano punti su cui le fonti raccontano versioni diverse. Vediamoli uno per uno.", [('punti', 'h:Le domande\n*aperte*'), ('versioni', 'stamp:VERSIONI DIVERSE')]),
 (10, "Primo: la data. La maggior parte delle fonti parla della notte del giorno 11 maggio 2003, ma un'agenzia di stampa francese scrive 12 maggio. Probabilmente per il modo di contare una notte a cavallo tra due giorni.", [('data', 'ii:calendar_x|11 MAGGIO?|calendar_x|12 MAGGIO?'), ('notte', 'i:moon|UNA NOTTE TRA DUE GIORNI')]),
 (10, "Poi le prime ore. Chi ha scoperto il furto: un capo dei sorveglianti o una donna delle pulizie? E il ladro si è presentato alla polizia il venerdì o il sabato? Anche qui, le ricostruzioni non coincidono.", [('scoperto', 'ii:guard2|UN SORVEGLIANTE?|woman|UNA ADDETTA?'), ('venerdì', 'ii:calendar_x|VENERDÌ?|calendar_x|SABATO?')]),
 (10, "Secondo: il valore. Cinquanta milioni di euro per alcune fonti, sessanta milioni di dollari per altre, e al processo si è parlato di almeno trentasei milioni di euro. Per un pezzo unico, ogni cifra è una stima.", [('valore', 'iii:eurobag|50 MLN €|eurobag|60 MLN $|eurobag|≥ 36 MLN €'), ('stima', 'stamp:SOLO STIME')]),
 (10, "Terzo: il riscatto. Cinque milioni di euro, sei milioni di dollari, dieci milioni di euro, e per un'agenzia americana fino a tredici milioni di dollari. Le cifre cambiano secondo le lettere e secondo le fonti.", [('riscatto', 'i:letter|QUANTO?'), ('dieci', 'big:5-10 mln €|le cifre del riscatto · fonti non concordi')]),
 (10, "Quarto: la cassa sepolta. Di legno per un'agenzia americana, di piombo per un grande quotidiano americano, solo una cassa per le altre fonti. E la distanza da Vienna cambia di qualche chilometro da un articolo all'altro.", [('cassa', 'ii:box_closed|DI LEGNO?|box_closed|DI PIOMBO?'), ('distanza', 'map:Zwettl|60|Vienna,Zwettl')]),
 (10, "Quinto: l'età del ladro. Cinquant'anni secondo la maggior parte delle fonti del 2006, quarantasette secondo un'altra ricostruzione. Qualcuno forse ha contato l'età al momento del furto, qualcuno al momento dell'arresto.", [("l'età", 'ii:calendar_x|50 ANNI?|calendar_x|47 ANNI?'), ("dell'arresto", 'stamp:FONTI NON CONCORDI')]),
 (10, "E c'è una domanda anche su Cellini. La sua Vita, l'autobiografia: per Britannica è stata completata nel 1562, per un'altra enciclopedia non è mai stata finita. Le versioni non coincidono nemmeno qui.", [('Cellini', 'i:quill|LA VITA DI CELLINI'), ('Britannica', 'ii:oldbook|COMPLETATA NEL 1562?|oldbook|MAI FINITA?')]),
 (10, "E infine la domanda più grande: davvero è stato tutto improvvisato, da un uomo che aveva bevuto? È la versione che il ladro ha dato al processo. Non sappiamo se sia tutta la verità: ne abbiamo solo il suo racconto.", [('domanda', 'i:question|IMPROVVISATO?'), ('versione', 'i:court|LA SUA VERSIONE'), ('racconto', 'stamp:SOLO IL SUO RACCONTO')]),
 (10, "Di sicuro, un esperto di allarmi sapeva meglio di chiunque altro come funziona un sistema di sicurezza, e anche cosa succede quando le persone che lo controllano si abituano ai falsi allarmi.", [('esperto', 'i:sensor|UN ESPERTO'), ('abituano', 'i:alarm_off|L\'ABITUDINE AI FALSI ALLARMI')]),
 # 11 LA LEZIONE
 (11, "Questa storia non riguarda solo i musei. Riguarda chiunque abbia un allarme a casa, in negozio o in ufficio. Ecco cinque idee che il caso della Saliera ci lascia.", [('musei', 'iii:museum|MUSEI|house|CASE|shop|NEGOZI'), ('cinque', 'check:1')]),
 (11, "Il punto di partenza è quello del vertice di Vienna: la tecnica, quella notte, aveva funzionato. È mancato il passo umano, la verifica. E vale anche per noi, ogni giorno.", [('tecnica', 'ii:sensor|LA TECNICA|guard2|LA VERIFICA'), ('umano', 'h:Il passo\n*umano*')]),
 (11, "Prima idea: un allarme non serve se nessuno controlla. Se il sistema suona, qualcuno deve andare a vedere, o chiamare chi può farlo. Un allarme spento senza verifica è come non averlo.", [('Prima', 'check:1'), ('controlla', 'flow:L\'ALLARME SUONA>QUALCUNO CONTROLLA')]),
 (11, "Seconda idea: i falsi allarmi sono pericolosi. Ogni falso allarme insegna alle persone a non fidarsi del sistema. Se il tuo suona spesso per niente, fallo sistemare subito.", [('Seconda', 'check:2'), ('falsi', 'i:alarm_off|L\'ABITUDINE'), ('sistemare', 'stamp:FALLO SISTEMARE')]),
 (11, "Terza idea: i lavori sono un momento a rischio. Un'impalcatura, un ponteggio, un cantiere aperto possono diventare una scala per chiunque. Quando ci sono lavori, la sicurezza va rinforzata, non abbassata.", [('Terza', 'check:3'), ("un'impalcatura", 'i:scaffold|UNA SCALA PER CHIUNQUE'), ('rinforzata', 'stamp:SICUREZZA RINFORZATA')]),
 (11, "Quarta idea: davanti a un ricatto non si tratta da soli. Si avvisano subito le forze dell'ordine, come hanno fatto il museo e l'assicurazione. È stato proprio il lavoro della polizia sul telefono a risolvere il caso.", [('Quarta', 'check:4'), ('forze', 'ii:police|FORZE DELL\'ORDINE|sms|LA TRACCIA DEL TELEFONO')]),
 (11, "Quinta idea: le opere rubate si segnalano. In Italia esiste il Comando dei carabinieri per la tutela del patrimonio culturale, con una banca dati delle opere rubate. Chi riconosce un oggetto sospetto può segnalarlo.", [('Quinta', 'check:5'), ('carabinieri', 'i:police|CARABINIERI · TUTELA PATRIMONIO CULTURALE'), ('banca', 'i:magnifier|LA BANCA DATI DELLE OPERE RUBATE')]),
 # IL VERDETTO
 (12, "Siamo al verdetto. Riassumiamo questo fascicolo in sei punti.", [('verdetto', 'cover'), ('sei', 'big:6 punti|il riepilogo')]),
 (12, "Uno: tra il 1540 e il 1543, a Parigi, Benvenuto Cellini crea per il re di Francia la Saliera, un capolavoro d'oro, smalto ed ebano. Due: dopo secoli e passaggi tra re e Asburgo, finisce nel museo di storia dell'arte di Vienna.", [('Uno', 'sal:0'), ('Due', 'map:Vienna|8|Parigi,Innsbruck,Vienna|Parigi>Innsbruck>Vienna')]),
 (12, "Tre: nella notte del giorno 11 maggio 2003 un uomo sale sull'impalcatura e la ruba, mentre l'allarme viene spento come falso. Quattro: nel 2005 chiede dieci milioni di riscatto e manda il tridente come prova.", [('Tre', 'mus:2'), ('Quattro', 'i:trident|IL TRIDENTE')]),
 (12, "Cinque: nel gennaio 2006 le immagini di una telecamera portano al ladro, un esperto di sistemi d'allarme, e la Saliera viene ritrovata in un bosco. Sei: condannato a cinque anni, ne sconta meno di tre. E l'opera, dal 2013, è di nuovo al suo posto.", [('Cinque', 'i:cctv|LA TELECAMERA'), ('bosco', 'i:box_open|IL BOSCO'), ('Sei', 'sal:3')]),
 (12, "E ora tocca a te. Secondo te, di chi è la colpa più grande: del ladro, o di chi quella notte ha spento l'allarme senza controllare? Scrivilo nei commenti.", [('tocca', 'h:Tocca a *te*'), ('colpa', 'ii:scaffold_man|IL LADRO?|alarm_off|L\'ALLARME SPENTO?'), ('commenti', 'stamp:SCRIVILO NEI COMMENTI')]),
 (12, "Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.", [('Iscriviti', 'subscribe')]),
]
